namespace bench {

// From bench/time.hpp and bench/scenario.hpp, as the earlier topics left them.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

struct Sample {
  Time at;
  double x_m = 0.0;
  double y_m = 0.0;
  double speed_mps = 0.0;
};

enum class Compare { at_least, at_most };

struct Check {
  std::string what;
  std::string unit;
  Compare compare;
  double limit;
  std::optional<double> measured;
};

[[nodiscard]] bool met(const Check& check) {
  if (!check.measured) return false;
  return check.compare == Compare::at_least ? *check.measured >= check.limit : *check.measured <= check.limit;
}

struct Verdict {
  std::string scenario;
  std::int64_t samples;
  bool passed;
  std::vector<Check> checks;
};

[[nodiscard]] Verdict judge(std::string scenario, std::int64_t samples, std::vector<Check> checks) {
  const bool passed = std::ranges::all_of(checks, met);
  return {.scenario = std::move(scenario), .samples = samples, .passed = passed, .checks = std::move(checks)};
}

namespace {

[[nodiscard]] std::string with_unit(double value, std::string_view unit) {
  return unit.empty() ? std::format("{:.2f}", value) : std::format("{:.2f} {}", value, unit);
}

[[nodiscard]] std::string line(const Check& check) {
  const std::string measured = check.measured ? with_unit(*check.measured, check.unit) : std::string("not measured");
  return std::format("{:<6} {}: {}, {} {}\n", met(check) ? "ok" : "failed", check.what, measured,
                     check.compare == Compare::at_least ? "at least" : "at most", with_unit(check.limit, check.unit));
}

}  // namespace

[[nodiscard]] std::string describe(const Verdict& verdict) {
  std::string text = std::format("{}\nscenario: {}\nsamples: {}\n", verdict.passed ? "pass" : "fail",
                                 verdict.scenario, verdict.samples);
  for (const Check& check : verdict.checks) text += line(check);
  return text;
}

[[nodiscard]] std::span<const Sample> between(std::span<const Sample> run, Time from, Time to) {
  const auto first = std::ranges::lower_bound(run, from, {}, &Sample::at);
  const auto last = std::ranges::upper_bound(run, to, {}, &Sample::at);
  if (first >= last) return {};
  return {first, last};
}

// New in this topic.

// The furthest the robot got from where this stretch started. A robot that crept away and came
// back reports the creep, which a first-to-last distance would hide.
[[nodiscard]] std::optional<double> wandered_m(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  const Sample& start = run.front();
  return std::ranges::max(run | std::views::transform([&start](const Sample& s) {
                            return std::hypot(s.x_m - start.x_m, s.y_m - start.y_m);
                          }));
}

// What "it held still" means, asked of one witness.
struct StopWindow {
  double wander_m;       // how far the robot may drift while it is meant to be stopped
  std::int64_t samples;  // the fewest samples that make the answer worth having
};

// The same question put to one witness. The runner asks it of the simulator's own state and of
// the wheel odometry, so both answers stand in the verdict next to each other.
[[nodiscard]] std::vector<Check> stop_checks(std::string_view witness, std::span<const Sample> stretch,
                                             const StopWindow& limits) {
  return {{.what = std::format("{}: samples while the robot was meant to be stopped", witness),
           .unit = "",
           .compare = Compare::at_least,
           .limit = static_cast<double>(limits.samples),
           .measured = static_cast<double>(std::ssize(stretch))},
          {.what = std::format("{}: distance from the stop point", witness),
           .unit = "m",
           .compare = Compare::at_most,
           .limit = limits.wander_m,
           .measured = wandered_m(stretch)}};
}

}  // namespace bench

// One reading of a witness, 200 ms of simulated time apart.
struct Moment {
  std::chrono::milliseconds t;
  double x_m;
};

[[nodiscard]] std::vector<bench::Sample> samples(std::span<const Moment> moments) {
  std::vector<bench::Sample> run;
  for (const Moment& moment : moments) {
    run.push_back({.at = {moment.t}, .x_m = moment.x_m, .y_m = 0.0, .speed_mps = 0.0});
  }
  return run;
}

[[nodiscard]] std::vector<bench::Sample> straight(double from_m, double step_m) {
  std::vector<Moment> moments;
  for (std::int64_t i = 0; i < 11; ++i) {
    moments.push_back({.t = std::chrono::milliseconds(200 * i), .x_m = from_m + step_m * static_cast<double>(i)});
  }
  return samples(moments);
}

int main() {
  using namespace std::chrono_literals;
  constexpr bench::StopWindow limits{.wander_m = 0.05, .samples = 5};
  const bench::Time stopped{0ms};
  const bench::Time odometry_back{2000ms};

  // The bench behaving: both witnesses say the robot held still for the two seconds it was
  // denied its odometry.
  const auto truth = straight(0.720, 0.0020);
  const auto wheels = straight(0.730, 0.0030);
  std::vector<bench::Check> agree =
      bench::stop_checks("simulator", bench::between(truth, stopped, odometry_back), limits);
  const std::vector<bench::Check> from_wheels =
      bench::stop_checks("odometry", bench::between(wheels, stopped, odometry_back), limits);
  agree.insert(agree.end(), from_wheels.begin(), from_wheels.end());
  std::cout << bench::describe(bench::judge("missing_odom", std::ssize(truth), std::move(agree)));
  std::cout << '\n';

  // The wheels lying: the encoders report a robot at rest while the simulator slides it 0.18 m.
  const auto frozen = straight(0.730, 0.0000);
  const auto sliding = straight(0.720, 0.0180);
  std::vector<bench::Check> disagree =
      bench::stop_checks("simulator", bench::between(sliding, stopped, odometry_back), limits);
  const std::vector<bench::Check> from_frozen =
      bench::stop_checks("odometry", bench::between(frozen, stopped, odometry_back), limits);
  disagree.insert(disagree.end(), from_frozen.begin(), from_frozen.end());
  std::cout << bench::describe(bench::judge("missing_odom", std::ssize(sliding), std::move(disagree)));
}

// In the constructor. The frame name comes from the model, so it is a parameter.
truth_frame_ = declare_parameter<std::string>("truth_frame", "turtlebot3_waffle");
truth_sub_ = create_subscription<tf2_msgs::msg::TFMessage>(
    "truth_tf", rclcpp::QoS(rclcpp::KeepLast(10)), [this](const tf2_msgs::msg::TFMessage& message) {
      for (const geometry_msgs::msg::TransformStamped& t : message.transforms) {
        if (t.child_frame_id != truth_frame_) continue;
        truth_run_.push_back({.at = {std::chrono::nanoseconds(rclcpp::Time(t.header.stamp).nanoseconds())},
                              .x_m = t.transform.translation.x,
                              .y_m = t.transform.translation.y});
      }
    });

// In finish(), after the missing-odometry checks: the stretch the robot had to hold still.
if (scenario_ == "missing_odom" && drop_cue_) {
  const bench::Time back{drop_cue_->since_epoch + drop_};
  const std::optional<bench::Time> rest = bench::first_rest(bench::since(run_, *drop_cue_), 0.01, 300ms);
  const bench::Time from = rest.value_or(*drop_cue_);
  const auto add = [&checks](std::vector<bench::Check> more) {
    checks.insert(checks.end(), more.begin(), more.end());
  };
  add(bench::stop_checks("simulator", bench::between(truth_run_, from, back), stop_window_));
  add(bench::stop_checks("odometry", bench::between(run_, from, back), stop_window_));
}

// In FakeInputs, which until now kept only the speeds. sent_ is the subscription and keeps its name.
struct Sent {
  rclcpp::Time at;
  double speed_mps;
};
// The /cmd_vel callback, in place of speeds_.push_back(command.twist.linear.x):
received_.push_back({.at = now(), .speed_mps = command.twist.linear.x});
// And in the timer, so the test measures from the moment odometry really stopped:
if (odometry_feed_ == Feed::on) { odometry_->publish(nav_msgs::msg::Odometry{}); last_odometry_ = now(); }

TEST_F(SupervisorTest, StopsWithinTheOdometryTimeout) {
  fake->odometry(Feed::on);
  fake->commands(Feed::on);
  ASSERT_TRUE(spin_until([&] { return std::ranges::count(fake->speeds(), 0.2) >= 5; }));
  fake->odometry(Feed::off);
  const rclcpp::Time last = fake->last_odometry();
  ASSERT_TRUE(spin_until([&] { return fake->first_stop_after(last).has_value(); }));
  EXPECT_LT((*fake->first_stop_after(last) - last).seconds(), 1.0);
}
